const $=s=>document.querySelector(s);
const paths={home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',cup:'M8 3h8v6a4 4 0 0 1-8 0z M8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4m-4 1v7m-4 1h8',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8m8-7a4 4 0 0 1 0 8m4 9v-2a4 4 0 0 0-3-3.87',chart:'M4 20V10m8 10V4m8 16v-7',user:'M20 21v-2a7 7 0 0 0-14 0v2 M13 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8m-2-5h4l1 3 3 1 2 3-2 2 1 3-3 3-3-1-2 2-3-2-1-3-2-1V8l3-1z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-9 13h6',search:'M21 21l-5-5 M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14',arrow:'M19 12H5m6-6-6 6 6 6',back:'M5 12h14m-6-6 6 6-6 6',plus:'M12 5v14M5 12h14',check:'M5 12l4 4L19 6',close:'M6 6l12 12M18 6 6 18',shield:'M12 3 3 6v6c0 5 9 9 9 9s9-4 9-9V6z M8 12l3 3 5-5',clock:'M12 8v5l3 2 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',calendar:'M4 5h16v16H4z M8 2v6m8-6v6M4 10h16',play:'M8 4l12 8-12 8z',bolt:'M13 2 4 14h7l-1 8 10-13h-7z',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',logout:'M9 3H4v18h5m5-15 6 6-6 6m6-6H9',edit:'m15 5 4 4M4 20l4-1L21 6l-4-4L4 15z'};
function icon(n,size=20){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.bolt}"/></svg>`}
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaultState={joined:false,squad:true,name:'אפי יתח',nick:'EfiX',requests:2,approved:false,results:false,roles:['Mid'],notifications:true};
let state;try{state={...defaultState,...JSON.parse(localStorage.getItem('nexus-demo')||'{}')}}catch{state={...defaultState}};
let filter='all',leaderType='players',detailTab='overview',squadTab='members',regStep=0,regChoice='',adminTab='overview';let route='home';
function save(){try{localStorage.setItem('nexus-demo',JSON.stringify(state))}catch{}}
const nav=[['home','home','בית'],['tournaments','cup','טורנירים'],['squad','users','הסקוואד שלי'],['leaderboard','chart','דירוגים'],['player','user','פרופיל שחקן']];
const badge=(t,c='')=>`<span class="badge ${c}">${c==='live'?'<i class="dot"></i>':''}${t}</span>`;
function avatar(t='EX',c='',lg=false){return `<span class="avatar ${c} ${lg?'lg':''}">${t}</span>`}
function btn(t,action,c=''){return `<button class="btn ${c}" onclick="${action}">${t}</button>`}
function go(r){location.hash=r;if(location.hash.slice(1)===r)render()}
function pageTitle(label,title,desc='',action=''){return `<div class="page-title"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function section(t,link='',action=''){return `<div class="section-head"><h2>${t}</h2>${link?`<button class="link" onclick="${action}">${link} ${icon('arrow',15)}</button>`:''}</div>`}
function renderShell(){const active=['tournament','live','register','match'].includes(route)?'tournaments':route;$('#sidebar').innerHTML=`<a class="brand" href="#home"><div class="brand-mark">${icon('bolt',27)}</div><div>NEXUS<small>COMPETE. CONNECT.</small></div></a><div class="game-switch"><span class="game-icon">M</span><div><b style="font-size:11px;direction:ltr;display:block">Mobile Legends</b><small class="muted" style="font-size:9px">המשחק שלך</small></div><span class="spacer"></span><span class="muted">⌄</span></div><div class="navlabel">הזירה שלך</div><nav class="sidenav">${nav.map(([r,i,t])=>`<a href="#${r}" ${r==='player'?"onclick=\"selectedPlayer='EfiX'\"":''} class="${active===r?'active':''}">${icon(i)}<span class="navtext">${t}</span>${r==='tournaments'?'<span class="nav-count">4</span>':''}</a>`).join('')}</nav><div class="side-bottom"><div class="side-tip"><strong>הקבוצה הבאה שלך כאן.</strong>שחקנים טובים יותר ביחד.<br><button class="link" style="margin-top:12px" onclick="openRecruit()">חיפוש שחקנים ${icon('arrow',14)}</button></div><nav class="sidenav"><a href="#admin" class="${route==='admin'?'active':''}">${icon('shield')}<span class="navtext">ניהול טורניר</span></a><a href="#settings" class="${route==='settings'?'active':''}">${icon('settings')}<span class="navtext">הגדרות חשבון</span></a></nav><div class="side-user">${avatar('EX')}<div><b>${escapeHTML(state.nick)}</b><small>פרופיל שחקן</small></div><button class="iconbtn" aria-label="מעבר לפרופיל" onclick="go('player')">${icon('arrow',16)}</button></div></div>`;$('#mobile-nav').innerHTML=nav.map(([r,i,t])=>`<a href="#${r}" ${r==='player'?"onclick=\"selectedPlayer='EfiX'\"":''} class="${active===r?'active':''}">${icon(i)}<span>${t==='הסקוואד שלי'?'סקוואד':t==='פרופיל שחקן'?'פרופיל':t}</span></a>`).join('');$('#topbar').innerHTML=`<div class="crumb">הזירה שלך <span style="padding:0 10px">/</span> <b>${({home:'סקירה כללית',tournaments:'טורנירים',squad:'סקוואד',leaderboard:'דירוגים',player:'פרופיל שחקן',settings:'הגדרות',admin:'ניהול טורניר',signup:'יצירת חשבון',tournament:'פרטי טורניר',live:'הטורניר בשידור',register:'הרשמה לטורניר',match:'מסך משחק'})[route]||'הזירה'}</b></div><a class="mobile-brand" href="#home"><span class="brand-mark">${icon('bolt',20)}</span>NEXUS</a><div class="top-tools"><div class="search">${icon('search',16)}<input aria-label="חיפוש טורנירים" placeholder="חיפוש טורניר..." onkeydown="if(event.key==='Enter')search(this.value)"></div><span class="demo-tag">תצוגת אבטיפוס</span><button class="iconbtn" aria-label="התראות" onclick="notifications()">${icon('bell')}<i class="notification-dot"></i></button><button class="iconbtn" aria-label="תפריט חשבון" onclick="accountMenu()">${avatar('EX')}</button></div>`}
const arenaArt=`<svg class="arena-art" viewBox="0 0 440 420" fill="none" aria-hidden="true"><defs><linearGradient id="a" x1="100" y1="80" x2="350" y2="380" gradientUnits="userSpaceOnUse"><stop stop-color="#e1ff9a"/><stop offset="1" stop-color="#60773b"/></linearGradient></defs><path d="M38 280 219 48 409 281 219 389Z" stroke="#b8d58b" stroke-opacity=".2"/><path d="M67 290 219 97 371 290 219 378Z" stroke="#b8d58b" stroke-opacity=".35"/><path d="m106 286 113-147 113 147-113 66Z" stroke="#b8d58b" stroke-opacity=".45"/><path d="M159 138h123v93c0 64-62 93-62 93s-61-30-61-93Z" fill="url(#a)"/><path d="m159 155-43 15 4 51c2 25 21 43 47 44m115-110 43 15-4 51c-2 25-21 43-47 44" stroke="#9ab964" stroke-width="16"/><path d="m222 164-31 47h24l-6 46 37-58h-25Z" fill="#324323"/><path d="M218 316v34m-38 9h79" stroke="#a6c574" stroke-width="10"/><circle cx="85" cy="110" r="3" fill="#defca3"/><circle cx="365" cy="168" r="4" fill="#defca3"/><path d="m330 68 16 16m0-16-16 16M60 330l12 12m0-12-12 12" stroke="#defca3" stroke-width="2"/></svg>`;
const tournaments=[{id:'tournament',title:'גביע הקהילה הישראלי',en:'COMMUNITY<br>CUP',type:'open',badge:'ההרשמה פתוחה',color:'lime',date:'29.10.2026 · 20:00',prize:'₪2,500',teams:'12 / 16',entry:'חינם',desc:'קבוצה אחת. חמישה שחקנים. הזדמנות לנצח.'},{id:'live',title:'ליגת הסתיו · מחזור 04',en:'AUTUMN<br>LEAGUE',type:'live',badge:'בשידור חי',color:'purple',date:'משחקי חצי הגמר',prize:'₪5,000',teams:'8 / 8',entry:'הליגה בעיצומה'},{id:'tournament',title:'טורניר הדור הבא',en:'NEXT<br>GEN',type:'soon',badge:'בקרוב',color:'orange',date:'05.11.2026 · 19:00',prize:'₪1,000',teams:'0 / 16',entry:'לשחקנים חדשים'}];
function card(t){return `<a class="tourney-card" href="#${t.id}" onclick="${t.type==='soon'?"event.preventDefault();openUpcoming()":"detailTab='overview'"}"><div class="tourney-cover cover-${t.color}"><div class="cover-word">${t.en}<small>MOBILE LEGENDS · ISRAEL</small></div>${badge(t.badge,t.type==='live'?'live':t.type==='soon'?'neutral':'')}</div><div class="tourney-body"><h3>${t.title}</h3><div class="meta">${icon('calendar',13)} ${t.date}</div><div class="tourney-data"><div><b>${t.prize}</b><small>סך פרסים</small></div><div><b dir="ltr">${t.teams}</b><small>קבוצות</small></div><div><b>${t.entry}</b><small>${t.type==='open'?'עלות כניסה':'מסגרת'}</small></div></div></div></a>`}
function playerCard(){return `<div class="panel"><div class="flex">${avatar('EX')}<div><b dir="ltr">${escapeHTML(state.nick)}</b><small class="muted" style="display:block;font-size:10px">שחקן · תפקיד ראשי Mid</small></div><span class="spacer"></span>${badge('PLATINUM','purple')}</div><div class="stats"><div class="stat"><span class="value">1,248</span><small>דירוג ELO</small></div><div class="stat"><span class="value positive">+86</span><small>בעונה הנוכחית</small></div><div class="stat"><span class="value">#24</span><small>בישראל</small></div></div><div class="flex between"><small class="muted">בדרך לדירוג הבא</small><small class="positive" dir="ltr">1,248 / 1,400</small></div><div class="progress"><i style="width:76%"></i></div><div class="small-row">${icon('shield',17)}<div><b>מוניטין מצוין</b><small>ללא הפרות פעילות</small></div><span class="spacer"></span><span class="positive">✓</span></div><button class="link" style="margin-top:16px" onclick="go('player')">לפרופיל המלא ${icon('arrow',15)}</button></div>`}
function home(){return `${pageTitle('YOUR NEXT LEVEL',`היי ${escapeHTML(state.name.split(' ')[0])}, הזירה מחכה לך.`, 'התחרות הבאה, הקבוצה שלך וההתקדמות שלך. הכל כאן.')}<div class="match-banner"><div class="event-icon">${icon('clock')}</div><div><b>${state.joined?'ההרשמה שלכם לגביע הקהילה הושלמה':'הסקוואד שלך חוזר לזירה ביום חמישי'}</b><small>${state.joined?'נותר לאשר נוכחות לפני תחילת הטורניר':'גביע הקהילה הישראלי · 29 באוקטובר, 20:00'}</small></div><span class="spacer"></span>${btn(state.joined?'למצב ההרשמה':'לפרטי הטורניר',"go('tournament')",'secondary small')}</div><div class="layout"><div><div class="hero">${arenaArt}<div class="hero-stamp">SEASON 01 / ISRAEL</div><div class="copy">${badge('4 מקומות אחרונים')}<h2>המשחק שלך.<br>הקבוצה שלך.<br><span style="color:var(--lime)">הרגע שלכם.</span></h2><p>גביע הקהילה הישראלי יוצא לדרך.<br>אספו את ההרכב והתחרו על ₪2,500.</p>${btn('תפסו מקום בטורניר '+icon('arrow',16),"go('tournament')")}</div></div>${section('הטורניר הבא שלכם','לכל הטורנירים',"go('tournaments')")}<div class="grid cols3 home-cards">${tournaments.map(card).join('')}</div>${section('עכשיו בזירה', 'לעץ הטורניר',"go('live')")}<div class="panel"><div class="flex between">${badge('LIVE','live')}<span class="muted" style="font-size:11px">ליגת הסתיו · חצי גמר</span></div><div class="versus" style="margin:20px 0"><div>${avatar('W','team')}<small>WOLFPACK</small></div><div class="score">1 <span class="muted">:</span> 0</div><div>${avatar('P','purple')}<small>PHANTOM</small></div></div><div class="flex between"><small class="muted">משחק 2 מתוך 3 · נתוני הדגמה</small>${btn(icon('play',14)+' צפייה בטורניר',"go('live')",'ghost small')}</div></div></div><div class="rail">${playerCard()}<div class="panel"><div class="flex between"><h3 style="margin:0">הסקוואד שלי</h3>${badge('קפטן','neutral')}</div><div class="small-row">${avatar('N','team')}<div><b>NOVA FIVE</b><small>5 שחקנים · הרכב מלא</small></div></div><div class="flex between" style="margin:16px 0"><span class="muted" style="font-size:11px">אחוז ניצחונות</span><b class="positive">68%</b></div>${btn('לניהול הסקוואד',"go('squad')",'secondary full')}</div><div class="panel"><div class="eyebrow" style="color:var(--purple)">FIND YOUR FIVE</div><h3 style="margin-top:10px">חסר לכם ה־Roamer הבא?</h3><p class="muted" style="font-size:12px">מצאו שחקנים שמתאימים להרכב ולסגנון המשחק שלכם.</p><button class="link" onclick="openRecruit()">למאגר השחקנים ${icon('arrow',15)}</button></div></div></div>`}
function tourneys(){let data=tournaments.filter(t=>filter==='all'||t.type===filter||(filter==='mine'&&state.joined&&t.type==='open'));return `${pageTitle('THE COMPETITION','טורנירים','בחרו את האתגר הבא שלכם.')}<div class="filters">${[['all','כל הטורנירים'],['open','הרשמה פתוחה'],['live','עכשיו בזירה'],['soon','בקרוב'],['mine','הטורנירים שלי']].map(([v,t])=>`<button class="tab ${filter===v?'active':''}" onclick="filter='${v}';render()">${t}</button>`).join('')}<span class="spacer"></span><span class="muted" style="font-size:11px">Mobile Legends · ישראל</span></div>${data.length?`<div class="grid cols3">${data.map(card).join('')}</div>`:`<div class="panel empty">${icon('cup',40)}<h2>הטורניר הראשון שלכם מחכה</h2><p>לאחר ההרשמה, תוכלו לעקוב כאן אחרי הטורנירים שלכם.</p>${btn('לטורנירים הפתוחים',"filter='open';render()")}</div>`}${section('איך נכנסים לתחרות?')}<div class="grid cols3">${[['users','עם הסקוואד שלכם','הקפטן בוחר הרכב, השחקנים מאשרים ואתם בפנים.'],['user','כשחקן יחיד','בחרו תפקיד ומצאו קבוצה שצריכה בדיוק אתכם.'],['plus','פותחים קבוצה','בנו הרכב חדש במיוחד לטורניר הקרוב.']].map(([i,t,d])=>`<div class="panel">${icon(i,25)}<h3 style="margin-top:15px">${t}</h3><p class="muted" style="font-size:12px">${d}</p></div>`).join('')}</div>`}
function bracket(){return `<div class="bracket"><div class="round"><h4>רבע גמר</h4>${[['NOVA FIVE','IRON CORE','2','0'],['WOLFPACK','RED FOX','2','1'],['PHANTOM','SOLAR','2','0'],['ONYX','TEAM ZERO','1','2']].map(x=>pair(...x)).join('')}</div><div class="round"><h4>חצי גמר</h4>${pair('NOVA FIVE','WOLFPACK','1','0')}${pair('PHANTOM','TEAM ZERO','0','0')}</div><div class="round"><h4>גמר</h4>${pair('מנצחת חצי גמר 1','מנצחת חצי גמר 2','–','–')}</div></div>`}
function pair(a,b,c,d){return `<div class="pair"><div class="${Number(c)>Number(d)?'won':''}"><span>${a}</span><b>${c}</b></div><div class="${Number(d)>Number(c)?'won':''}"><span>${b}</span><b>${d}</b></div></div>`}
function detail(live=false){return `<a class="back" href="#tournaments">${icon('back',16)} חזרה לטורנירים</a><div class="detail-banner"><div class="flex between">${badge(live?'בשידור חי':'ההרשמה פתוחה',live?'live':'')}<span class="muted" style="font-size:10px">MOBILE LEGENDS / 5V5</span></div><h1>${live?'ליגת הסתיו · מחזור 04':'גביע הקהילה הישראלי'}</h1><p>${live?'ארבע קבוצות. כרטיס אחד לגמר.':'קבוצה אחת. חמישה שחקנים. הזדמנות לנצח.'}</p><div class="stats"><div class="stat"><span class="value">${live?'₪5,000':'₪2,500'}</span><small>סך פרסים</small></div><div class="stat"><span class="value">${live?'8 / 8':'12 / 16'}</span><small>קבוצות רשומות</small></div><div class="stat"><span class="value">${live?'חצי גמר':'29.10'}</span><small>${live?'שלב בתחרות':'יום חמישי · 20:00'}</small></div></div></div><div class="tabs-line">${[['overview','סקירה כללית'],['bracket','עץ הטורניר'],['teams','קבוצות משתתפות'],['rules','חוקים ופרסים']].map(([v,t])=>`<button class="tab ${detailTab===v?'active':''}" onclick="detailTab='${v}';render()">${t}</button>`).join('')}</div><div class="layout"><div>${detailTab==='bracket'?`<div class="panel"><h3>הדרך לגמר</h3>${live?'':'<p class="muted" style="font-size:12px">תצוגה מקדימה של מבנה התחרות. השיבוץ הרשמי יפורסם לאחר נעילת ההרכבים.</p>'}${bracket()}</div>`:detailTab==='teams'?`<div class="panel"><h3>על קו הזינוק</h3>${['NOVA FIVE','WOLFPACK','PHANTOM','TEAM ZERO','IRON CORE','RED FOX'].map((n,i)=>`<div class="small-row">${avatar(n[0],i%2?'purple':'team')}<div><b>${n}</b><small>5 שחקנים · הרכב מאושר</small></div><span class="spacer"></span>${badge('מאושרת')}</div>`).join('')}</div>`:detailTab==='rules'?`<div class="panel"><h3>מבנה ותקנון</h3><p>משחקי 5 נגד 5 בשיטת נוקאאוט. כל מפגש הוא סדרה של הטוב משלושה. כל קבוצה רשאית לרשום חמישה שחקנים ועד שני מחליפים.</p><p>נעילת הרכבים: 28.10 בשעה 20:00. אישור נוכחות נפתח שעה לפני תחילת התחרות. שינוי בהרכב נעול דורש אישור מנהל.</p><h3 style="margin-top:25px">חלוקת פרסים לדוגמה</h3><div class="small-row"><span>מקום ראשון</span><span class="spacer"></span><b>₪1,500</b></div><div class="small-row"><span>מקום שני</span><span class="spacer"></span><b>₪750</b></div><div class="small-row"><span>מקום שלישי</span><span class="spacer"></span><b>₪250</b></div><p class="skeleton-note">התקנון והסכומים נועדו להמחשה באבטיפוס.</p></div>`:`${live?`<div class="stream"><div><button class="play" aria-label="הפעלת תצוגת שידור" onclick="streamDemo()">${icon('play',28)}</button><h3>WOLFPACK vs PHANTOM</h3><span class="muted">אזור לשידור חי · תצוגה לדוגמה</span></div></div>`:`<div class="panel"><h3>הבמה הבאה של הסקוואד שלכם</h3><p class="muted">גביע קהילתי לשחקני מובייל לגנדס בישראל. הזדמנות להכיר קבוצות, לצבור ניסיון תחרותי ולטפס בדירוג. אפשר להצטרף עם קבוצה קיימת או למצוא הרכב דרך הפלטפורמה.</p><div class="check-line">${icon('check',17)} הרשמה חינמית לקבוצות ולשחקנים יחידים</div><div class="check-line">${icon('check',17)} כל התפקידים וכל רמות הניסיון</div><div class="check-line">${icon('check',17)} תוצאות מאומתות והיסטוריה בפרופיל</div></div>`}${section(live?'המשחק עכשיו':'לוח זמנים')}<div class="panel">${live?`<div class="versus"><div>${avatar('W','team',true)}<small>WOLFPACK</small></div><div class="score">1 : 0</div><div>${avatar('P','purple',true)}<small>PHANTOM</small></div></div><div style="margin-top:25px">${btn('למסך המשחק',"go('match')",'secondary full')}</div>`:[['27.10 · 23:59','סגירת הרשמה'],['28.10 · 20:00','נעילת הרכבים'],['29.10 · 19:00','פתיחת אישור נוכחות'],['29.10 · 20:00','יוצאים לדרך']].map(([a,b])=>`<div class="small-row">${icon('clock',17)}<b>${b}</b><span class="spacer"></span><span class="muted" dir="ltr">${a}</span></div>`).join('')}</div>`}</div><div><div class="panel"><h3>${live?'מצב התחרות':state.joined?'אתם בפנים!':'נפגשים בזירה'}</h3><p class="muted" style="font-size:12px">${live?'הטורניר בשלב חצי הגמר. תוצאות המשחקים מופיעות לאחר אישור מנהל.':state.joined?'NOVA FIVE רשומה לגביע הקהילה. ההרכב שלכם מוכן לתחרות.':'נותרו 4 מקומות לקבוצות. ההרשמה נסגרת ב־27 באוקטובר.'}</p>${state.joined&&!live?badge('ההרשמה מאושרת'):''}<div class="progress"><i style="width:${live?100:75}%"></i></div>${live?btn('צפייה בעץ הטורניר',"detailTab='bracket';render()",'full'):btn(state.joined?'צפייה בהרכב שלי':'הרשמה לטורניר',state.joined?"go('squad')":"regStep=0;regChoice='';go('register')",'full')}<p style="font-size:10px;text-align:center" class="muted">${live?'נתוני תחרות לדוגמה':'ללא דמי הרשמה · חמישה שחקנים בהרכב'}</p></div><div class="panel"><div class="mini-label">מארגני הטורניר</div><div class="flex">${avatar('N','team')}<div><b>Nexus Community</b><small class="muted" style="display:block">צוות ניהול התחרות</small></div></div><button class="link" style="margin-top:20px" onclick="support()">פנייה למנהל ${icon('arrow',15)}</button></div></div></div>`}
function register(){return `<a class="back" href="#tournament">${icon('back',16)} חזרה לטורניר</a>${pageTitle('TAKE YOUR PLACE','הרשמה לגביע הקהילה','בחרו איך תרצו להיכנס לזירה.')}<div style="max-width:760px;margin:auto"><div class="steps"><span class="${regStep===0?'active':''}">01 בחירת מסלול</span><span class="${regStep===1?'active':''}">02 פרטי ההרכב</span><span class="${regStep===2?'active':''}">03 אישור הרשמה</span></div>${regStep===0?`<div class="panel"><h2>איך אתם מצטרפים?</h2>${[['squad','users','עם הסקוואד שלי','רישום NOVA FIVE ובחירת ההרכב לטורניר.'],['solo','user','אני מחפש קבוצה','בחירת תפקידים והצטרפות למאגר השחקנים של הטורניר.'],['new','plus','פותחים קבוצה לטורניר','הקמת קבוצה זמנית והזמנת שחקנים להשלמת ההרכב.']].map(([v,i,t,d])=>`<button class="choice ${regChoice===v?'active':''}" onclick="regChoice='${v}';render()">${icon(i,25)}<div><b>${t}</b><small>${d}</small></div><span class="spacer"></span>${regChoice===v?icon('check'):icon('arrow',17)}</button>`).join('')}${btn('המשך '+icon('arrow',16),"nextReg()",'full')}</div>`:regStep===1?regDetails():`<div class="panel empty"><span style="color:var(--lime)">${icon('shield',65)}</span><h2>${regChoice==='solo'?'אתה במאגר השחקנים!':regChoice==='new'?'הקבוצה נפתחה לטורניר!':'NOVA FIVE נכנסת לזירה!'}</h2><p>${regChoice==='solo'?'קפטנים יוכלו למצוא אותך לפי התפקידים שבחרת. המקום בטורניר יובטח רק לאחר הצטרפות להרכב מאושר.':regChoice==='new'?'כעת אפשר לגייס שחקנים. ההרשמה לטורניר תושלם לאחר מילוי ההרכב ואישור המשתתפים.':'ההרשמה אושרה בסביבת ההדגמה. נזכיר לכם לאשר נוכחות לפני פתיחת התחרות.'}</p>${btn(regChoice==='solo'?'למציאת קבוצה':regChoice==='new'?'לניהול הקבוצה':'לפרטי הטורניר',regChoice==='solo'?"state.squad=false;save();go('squad')":regChoice==='new'?"state.squad=true;save();go('squad')":"go('tournament')")}</div>`}</div>`}
const members=[['EfiX','Mid','EX','1,248','68%'],['Shadow','Jungle','SH','1,390','72%'],['Kairo','EXP','KA','1,285','64%'],['Luna','Gold','LU','1,312','70%'],['Mochi','Roam','MO','1,190','66%']];
function memberRows(selectable=false){return members.map(([n,r,a,e,w],i)=>`<tr><td><div class="flex">${avatar(a,i%2?'purple':'team')}<b dir="ltr">${n}</b>${i===0?badge('קפטן','neutral'):''}</div></td><td><span class="role">${r}</span></td><td dir="ltr">${e}</td><td class="positive">${w}</td><td>${selectable?badge('אישר השתתפות'):i?`<button class="iconbtn" aria-label="ניהול ${n}" onclick="manageMember('${n}')">${icon('edit',15)}</button>`:badge('אתה','neutral')}</td></tr>`).join('')}
function rolePicker(){return `<div class="tagrow">${['Mid','Jungle','EXP','Gold','Roam'].map(r=>`<button type="button" class="role ${state.roles.includes(r)?'selected':''}" onclick="toggleRole('${r}',this)">${r}</button>`).join('')}</div>`}
function regDetails(){return `<div class="panel"><h2>${regChoice==='squad'?'ההרכב שלכם לטורניר':regChoice==='solo'?'מה התפקיד שלך בהרכב?':'בואו נקים את הקבוצה'}</h2>${regChoice==='squad'?`<p class="muted">בחרנו את ההרכב הראשי של NOVA FIVE. כל חמשת השחקנים אישרו השתתפות בנתוני ההדגמה.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>שחקן</th><th>תפקיד</th><th>ELO</th><th>ניצחונות</th><th>מצב</th></tr></thead><tbody>${memberRows(true)}</tbody></table></div>`:regChoice==='solo'?`<p>בחר את התפקידים שבהם תרצה לשחק. התפקיד הראשון שתבחר יהיה התפקיד הראשי.</p>${rolePicker()}<div class="notice">הפרופיל שלך יוצג לקפטנים שמחפשים שחקנים לטורניר. הצטרפות למאגר אינה הרשמה מאושרת לתחרות.</div>`:`<div class="form-field" style="margin-top:20px"><label for="new-team-name">שם הקבוצה</label><input id="new-team-name" placeholder="למשל NOVA FIVE" maxlength="30"></div><label for="join-policy">אופן הצטרפות</label><select id="join-policy"><option>באישור קפטן</option><option>הצטרפות פתוחה</option><option>בהזמנה בלבד</option></select><p class="muted">הקבוצה תתחיל איתך כקפטן. ניתן יהיה להזמין שחקנים ולפרסם תפקידים חסרים.</p>`}<label class="check-line" style="margin-top:22px"><input id="rules-check" type="checkbox" style="width:17px;accent-color:var(--lime)"> קראתי ואני מאשר את חוקי הטורניר</label><div class="flex" style="margin-top:20px">${btn('חזרה',"regStep=0;render()",'ghost')}${btn(regChoice==='solo'?'הצטרפות למאגר':regChoice==='new'?'יצירת קבוצה':'אישור הרשמה',"completeReg()",'full')}</div></div>`}
function squad(){return `${pageTitle('BETTER TOGETHER','הסקוואד שלי',state.squad?'ההרכב, האנשים והדרך שלכם קדימה.':'מצאו את האנשים לשחק איתם.',btn(state.squad?'תצוגה ללא סקוואד':'יש לי סקוואד',"state.squad=!state.squad;save();render()",'ghost small'))}${state.squad?`<div class="profile-head"><div class="squad-crest">N</div><div><div class="eyebrow">EST. 2026</div><h1 dir="ltr">${escapeHTML(state.teamName||'NOVA FIVE')}</h1><p class="muted" style="margin:3px 0">חמישה שחקנים. מטרה משותפת.</p></div><span class="spacer"></span>${badge('קפטן הקבוצה','purple')}${btn(icon('plus',16)+' הזמנת שחקנים',"openRecruit()",'secondary')}</div><div class="grid cols3 metrics" style="margin-top:20px"><div class="metric"><small>דירוג סקוואד</small><b class="number">1,320</b><span class="positive">מקום 8 בישראל</span></div><div class="metric"><small>אחוז ניצחונות</small><b class="number">68%</b><span class="muted">17 מתוך 25 משחקים</span></div><div class="metric"><small>טורנירים</small><b class="number">6</b><span class="muted">זכייה אחת · 2 הופעות בגמר</span></div></div><div class="tabs-line">${[['members','חברי הסקוואד'],['requests',`בקשות הצטרפות (${state.requests})`],['history','טורנירים והישגים']].map(([v,t])=>`<button class="tab ${squadTab===v?'active':''}" onclick="squadTab='${v}';render()">${t}</button>`).join('')}</div><div class="panel">${squadTab==='members'?`<div class="flex between"><h3>ההרכב שלנו</h3><span class="muted" style="font-size:11px">5 שחקנים פעילים</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>שחקן</th><th>תפקיד</th><th>ELO</th><th>אחוז ניצחונות</th><th>ניהול</th></tr></thead><tbody>${memberRows()}</tbody></table></div><div class="notice">הרכבים לטורנירים מנוהלים בנפרד מחברות בסקוואד. הסרת חבר לא תשנה הרכב שכבר ננעל.</div>`:squadTab==='requests'?state.requests?`<h3>שחקנים שרוצים להצטרף</h3>${['NinjaIL','Pixel'].filter(n=>!(state.handledRequests||[]).includes(n)).map((n,i)=>`<div class="small-row">${avatar(n[0],i?'orange':'blue')}<div><b>${n}</b><small>${i?'Jungle':'Roam'} · דירוג ${i?'1,290':'1,260'}</small></div><span class="spacer"></span>${btn('אישור',`approveRequest('${n}')`,'small')}${btn('דחייה',`rejectRequest('${n}')`,'ghost small')}</div>`).join('')}`:'<div class="empty"><h3>כל הבקשות טופלו</h3><p>בקשות חדשות יופיעו כאן.</p></div>':historyTable()}</div>`:`<div class="panel"><h2>הסקוואד הבא שלך מחכה כאן</h2><p class="muted">מצא קבוצה לפי התפקיד שלך והתחל להתחרות.</p><div class="flex wrap">${rolePicker()}<span class="spacer"></span>${btn('פתיחת סקוואד '+icon('plus',15),"createSquad()")}</div></div><div class="grid cols3" style="margin-top:20px">${[['WOLFPACK','Roam','1,290'],['PHANTOM','Mid','1,180'],['SOLAR FIVE','Gold','1,350']].map(([n,r,e],i)=>`<div class="panel">${avatar(n[0],i%2?'purple':'team',true)}<h3 style="margin-top:15px">${n}</h3><p class="muted" style="font-size:12px">מחפשים שחקן ${r} להרכב תחרותי.<br>זמינים בערבים · דירוג קבוצתי ${e}</p><span class="role">${r}</span><div style="margin-top:20px">${btn(state['request'+n]?'הבקשה נשלחה':'בקשת הצטרפות',`requestSquad('${n}')`,'secondary full')}</div></div>`).join('')}</div>`}`}
function historyTable(){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>טורניר</th><th>תאריך</th><th>מיקום</th><th>פרס</th></tr></thead><tbody>${[['גביע פתיחת העונה','12.10.2026','מקום 1','₪1,000'],['ליגת הקהילה','01.10.2026','מקום 2','₪500'],['טורניר סוף הקיץ','20.09.2026','מקום 4','—']].map(([t,d,r,m])=>`<tr><td><a href="#live">${t}</a></td><td dir="ltr">${d}</td><td>${badge(r,r.includes('1')?'':'neutral')}</td><td>${m}</td></tr>`).join('')}</tbody></table></div>`}
const leaderboardPlayers=[['Shadow','Jungle','1,690','76%'],['Kairo','EXP','1,625','72%'],['Luna','Gold','1,580','74%'],['Mochi','Roam','1,512','69%'],['NinjaIL','Mid','1,480','67%'],['EfiX','Mid','1,248','68%']];
function leaders(){const teams=leaderType==='teams';const data=teams?[['WOLFPACK','5 שחקנים','1,590','78%'],['PHANTOM','5 שחקנים','1,520','72%'],['NOVA FIVE','5 שחקנים','1,320','68%'],['TEAM ZERO','6 שחקנים','1,290','65%']]:leaderboardPlayers;return `${pageTitle('THE RANKINGS','מי מוביל את הזירה?','דירוג עונתי המבוסס על תוצאות תחרויות בפלטפורמה.')}<div class="flex wrap between"><div class="filters">${[['players','שחקנים'],['teams','סקוואדים']].map(([v,t])=>`<button class="tab ${leaderType===v?'active':''}" onclick="leaderType='${v}';render()">${t}</button>`).join('')}</div><span class="role">עונה 01 · אוקטובר 2026</span></div><div class="podium">${[data[1],data[0],data[2]].map((x,i)=>`<div class="panel ${i===1?'top':''}"><div class="mini-label">מקום ${[2,1,3][i]}</div>${avatar(x[0].slice(0,2),i===1?'team':'purple',true)}<h3>${x[0]}</h3><span class="muted">${x[2]} ELO</span></div>`).join('')}</div><div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>מיקום</th><th>${teams?'סקוואד':'שחקן'}</th><th>${teams?'הרכב':'תפקיד ראשי'}</th><th>ELO</th><th>ניצחונות</th><th>שינוי</th></tr></thead><tbody>${data.map(([n,r,e,w],i)=>`<tr class="${n==='EfiX'||n==='NOVA FIVE'?'me':''}"><td class="rank">${n==='EfiX'?'24':i+1}</td><td><a class="flex" href="#${teams?'squad':'player'}" onclick="${teams?'':`selectedPlayer='${n}'`}">${avatar(n.slice(0,2),i%2?'purple':'team')}<b>${n}</b>${n==='EfiX'?badge('אתה','neutral'):''}</a></td><td>${r}</td><td dir="ltr">${e}</td><td>${w}</td><td class="positive" dir="ltr">↑ ${[2,1,3,2,4,6][i]||2}</td></tr>`).join('')}</tbody></table></div></div><p class="notice">הדירוג התחרותי נפרד מהמוניטין ההתנהגותי. כל הנתונים כאן הם נתוני הדגמה.</p>`}
let selectedPlayer='EfiX';
function player(){let mine=selectedPlayer==='EfiX';return `${pageTitle('PLAYER ID','פרופיל שחקן','ההתקדמות וההישגים שלך בזירה.')}<div class="profile-head">${avatar(mine?'EX':selectedPlayer.slice(0,2),'',true)}<div><div class="flex"><h1 dir="ltr">${mine?escapeHTML(state.nick):selectedPlayer}</h1>${badge('PLATINUM','purple')}</div><div class="muted" style="font-size:12px">Mobile Legends · ישראל · ${mine?'NOVA FIVE':'WOLFPACK'}</div><div class="tagrow"><span class="role">Mid</span><span class="role">Gold</span></div></div><span class="spacer"></span>${btn(mine?icon('edit',15)+' עריכת פרופיל':icon('plus',15)+' הזמנה לסקוואד',mine?"go('settings')":`invite('${selectedPlayer}')`,'secondary')}</div><div class="grid cols3 metrics" style="margin-top:20px"><div class="metric"><small>דירוג ELO</small><b class="number">${mine?'1,248':'1,690'}</b><span class="positive">↑ 86 בעונה</span></div><div class="metric"><small>אחוז ניצחונות</small><b class="number">68%</b><span class="muted">17 ניצחונות מתוך 25 משחקים</span></div><div class="metric"><small>יחס הריגות ואסיסטים למיתות</small><b class="number">4.8</b><span class="muted">בהתבסס על תוצאות מאושרות</span></div></div><div class="layout" style="margin-top:22px"><div><div class="panel"><div class="flex between"><h3>ההתקדמות שלך</h3>${badge('+86 ELO')}</div><div class="chart">${[25,40,33,55,62,58,75,86,93,100].map((n,i)=>`<i style="height:${n}%"><span>${i%3===0?`${i+1}.10`:''}</span></i>`).join('')}</div><p class="muted" style="font-size:10px;margin-top:35px">תצוגת התקדמות לדוגמה במהלך העונה</p></div>${section('היסטוריית טורנירים')}<div class="panel">${historyTable()}</div></div><div><div class="panel"><div class="flex">${icon('shield',25)}<h3 style="margin:0">מוניטין מצוין</h3></div><p class="muted" style="font-size:12px">ללא הפרות פעילות. הופעה בזמן והשלמת משחקים ב־10 המשחקים האחרונים.</p>${badge('ללא הפרות')}</div><div class="panel"><h3>ארון ההישגים</h3><div class="small-row"><span class="positive">${icon('cup',27)}</span><div><b>הזכייה הראשונה</b><small>גביע פתיחת העונה · מקום 1</small></div></div><div class="small-row"><span style="color:var(--purple)">${icon('bolt',27)}</span><div><b>חמישה ברצף</b><small>רצף של 5 ניצחונות</small></div></div></div></div></div>`}
function settings(){return `${pageTitle('YOUR ACCOUNT','הגדרות חשבון','המידע האישי, פרופיל המשחק והעדפות ההתראות.')}<div class="layout"><div><form class="panel" onsubmit="saveSettings(event)"><h3>הפרטים שלך</h3><div class="form-grid" style="margin-top:22px"><div class="form-field"><label for="account-name">שם תצוגה</label><input id="account-name" required maxlength="40" value="${escapeHTML(state.name)}"></div><div class="form-field"><label for="account-nick">כינוי במשחק</label><input id="account-nick" required maxlength="24" dir="ltr" value="${escapeHTML(state.nick)}"></div><div class="form-field"><label for="account-email">כתובת דואר אלקטרוני</label><input id="account-email" type="email" value="player@example.com" dir="ltr"></div><div class="form-field"><label for="game-id">מזהה שחקן במשחק</label><input id="game-id" value="123456789" dir="ltr"></div></div><label for="member-card">מספר כרטיס שחקן בעמותת הגיימינג</label><input id="member-card" value="${escapeHTML(state.card||'')}" placeholder="אופציונלי" maxlength="30"><p class="hint">מספר שהוזן אינו כרטיס מאומת. אימות אינו פעיל באבטיפוס.</p><label style="margin-top:22px">תפקידים מועדפים</label>${rolePicker()}<div style="margin-top:25px"><button class="btn" type="submit">שמירת שינויים</button></div></form><div class="panel"><h3>העדפות</h3>${[['התראות לקראת משחק','תזכורות ואישור נוכחות'],['הזמנות לסקוואד','אפשר לקפטנים לשלוח הזמנות'],['פרופיל ציבורי','הצגת הישגים ודירוג לשחקנים אחרים']].map(([t,d],i)=>`<div class="small-row"><div><b>${t}</b><small>${d}</small></div><span class="spacer"></span><button class="toggle ${state['toggle'+i]===false?'off':''}" aria-label="${t}" aria-pressed="${state['toggle'+i]!==false}" onclick="togglePreference(${i},this)"></button></div>`).join('')}</div></div><div><div class="panel"><h3>כל מסכי האבטיפוס</h3><p class="muted" style="font-size:12px">אפשר לעבור גם לתצוגות שאינן חלק מהניווט הרגיל של שחקן.</p><div class="sidenav"><a href="#signup">${icon('user')}מסך הרשמה</a><a href="#admin">${icon('shield')}ניהול טורניר</a><a href="#match">${icon('bolt')}מסך משחק</a></div></div><div class="panel"><h3>נתוני ההדגמה</h3><p class="muted" style="font-size:12px">השינויים נשמרים בדפדפן הזה לצורך הדגמה. אין כאן חשבון משתמש אמיתי.</p>${btn('איפוס ההדגמה',"resetDemo()",'ghost full')}</div></div></div>`}
let signupStep=0;
function signup(){return `${pageTitle('WELCOME TO THE ARENA','הדרך שלך לזירה מתחילה כאן','פותחים חשבון, בונים פרופיל ומוצאים את ההרכב שלכם.')}<div class="grid cols2"><div class="panel"><div class="steps"><span class="${signupStep===0?'active':''}">01 חשבון</span><span class="${signupStep===1?'active':''}">02 פרופיל שחקן</span></div><form onsubmit="signupSubmit(event)">${signupStep===0?`<h2>נעים להכיר.</h2><p class="muted">כמה פרטים ונתחיל.</p><div class="form-field"><label for="signup-name">שם תצוגה</label><input id="signup-name" required placeholder="איך קוראים לך?" maxlength="40"></div><div class="form-field"><label for="signup-email">דואר אלקטרוני</label><input id="signup-email" type="email" required dir="ltr" placeholder="you@example.com"></div><p class="hint">זהו תהליך הדגמה בלבד. אין צורך בסיסמה ולא ייפתח חשבון אמיתי.</p>`:`<h2>הזהות שלך במשחק</h2><p class="muted">כך יכירו אותך בזירה.</p><div class="form-field"><label for="signup-nick">כינוי במשחק</label><input id="signup-nick" required dir="ltr" placeholder="Your nickname" maxlength="24"></div><div class="form-field"><label for="signup-id">מזהה שחקן</label><input id="signup-id" required dir="ltr" placeholder="Player ID"></div><label>תפקידים מועדפים</label>${rolePicker()}<div class="form-field" style="margin-top:20px"><label for="signup-card">מספר כרטיס שחקן</label><input id="signup-card" placeholder="אופציונלי · עמותת הגיימינג"></div><label for="signup-status">מה מתאר אותך?</label><select id="signup-status"><option value="solo">מחפש קבוצה</option><option value="team">יש לי קבוצה</option></select>`}<button class="btn full" style="margin-top:22px" type="submit">${signupStep===0?'ממשיכים לפרופיל שחקן':'כניסה לזירה'} ${icon('arrow',16)}</button></form></div><div class="hero" style="min-height:450px">${arenaArt}<div class="copy" style="max-width:90%"><div class="eyebrow">FIND YOUR FIVE</div><h2>יותר ממשחק.<br>המקום שלך<br><span class="positive">להתחרות.</span></h2><p>טורנירים, שחקנים וסקוואדים.<br>כל הדרך מהמשחק הראשון לזכייה הבאה.</p></div></div></div>`}
function admin(){return `${pageTitle('TOURNAMENT CONTROL','ניהול גביע הקהילה','הרשאה לטורניר הזה בלבד · מנהל טורניר',btn('לצפייה כשחקן',"go('tournament')",'secondary'))}<div class="grid cols3 metrics"><div class="metric"><small>קבוצות רשומות</small><b class="number">12 <span class="muted" style="font-size:16px">/ 16</span></b><span class="positive">75% מהקיבולת</span></div><div class="metric"><small>ממתינות לאישור</small><b class="number">${state.approved?'0':'1'}</b><span class="muted">${state.approved?'כל הבקשות טופלו':'קבוצה עם הרכב מלא'}</span></div><div class="metric"><small>תוצאות לבדיקה</small><b class="number">${state.results?'0':'1'}</b><span class="muted">${state.results?'התוצאה אושרה':'ממתינה לאישור מנהל'}</span></div></div><div class="tabs-line">${[['overview','סקירה ובקשות'],['results','תוצאות וצילומי מסך'],['edit','פרטי הטורניר'],['log','יומן פעולות']].map(([v,t])=>`<button class="tab ${adminTab===v?'active':''}" onclick="adminTab='${v}';render()">${t}</button>`).join('')}</div>${adminTab==='overview'?`<div class="panel"><div class="flex between"><h3>בקשות הרשמה</h3>${badge(state.approved?'אין בקשות פתוחות':'בקשה אחת ממתינה','neutral')}</div>${state.approved?'<div class="empty"><h3>כל הבקשות טופלו</h3><p>TEAM ZERO אושרה לטורניר.</p></div>':`<div class="small-row">${avatar('TZ','blue')}<div><b>TEAM ZERO</b><small>5 שחקנים · ההרכב מלא · כל האישורים התקבלו</small></div><span class="spacer"></span>${btn('אישור קבוצה',"state.approved=true;save();render();toast('TEAM ZERO אושרה לטורניר')",'small')}</div>`}</div><div class="panel"><h3>פעולות מהירות</h3><div class="flex wrap" style="margin-top:20px">${btn('עריכת פרטים',"adminTab='edit';render()",'secondary')}${btn('ניהול תוצאות',"adminTab='results';render()",'secondary')}${btn('צפייה בעץ הטורניר',"detailTab='bracket';go('tournament')",'ghost')}</div></div>`:adminTab==='results'?`<div class="admin-alert">ניתוח צילומי המסך מוצג כאן כהדגמת תהליך. הנתונים אינם מחולצים מתמונה בפועל ואינם נשלחים לשירות חיצוני.</div><div class="panel"><h3>הוספת צילום תוצאה</h3><p class="muted">בחרו תמונה כדי להמחיש את שלב העלאת הראיה. לאחר מכן תיפתח טבלת דוגמה לבדיקה ולתיקון.</p><label for="result-image">צילום מסך מהמשחק</label><input id="result-image" type="file" accept="image/*" onchange="resultUpload(this)"><div id="result-preview" style="margin-top:15px"></div></div><div class="panel"><div class="flex between"><h3>NOVA FIVE מול IRON CORE</h3>${badge(state.results?'תוצאה מאושרת':'ממתינה לבדיקה',state.results?'':'neutral')}</div><p class="muted">טבלת נתוני דוגמה · משחק ראשון ברבע הגמר</p><div class="table-wrap"><table class="data-table"><thead><tr><th>שחקן</th><th>הריגות</th><th>מיתות</th><th>אסיסטים</th></tr></thead><tbody>${members.map(([n],i)=>`<tr><td>${n}</td>${[8-i,2+i%2,6+i].map((v,j)=>`<td><input type="number" min="0" max="99" value="${v}" aria-label="${['הריגות','מיתות','אסיסטים'][j]} ${n}" style="width:65px;padding:6px" ${state.results?'disabled':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="flex wrap" style="margin-top:20px">${btn(state.results?'התוצאה אושרה':'אישור ופרסום תוצאה',"approveResult()",state.results?'ghost':'')}<span class="muted" style="font-size:11px">עדכון נתוני דוגמה בלבד</span></div></div>`:adminTab==='edit'?`<form class="panel" onsubmit="event.preventDefault();toast('פרטי הטורניר נשמרו בהדגמה')"><h3>פרטי הטורניר</h3><div class="form-grid" style="margin-top:20px"><div class="form-field"><label for="admin-title">שם הטורניר</label><input id="admin-title" value="גביע הקהילה הישראלי" required></div><div class="form-field"><label for="admin-date">מועד התחלה</label><input id="admin-date" type="datetime-local" value="2026-10-29T20:00" required></div><div class="form-field"><label for="admin-teams">מספר קבוצות מרבי</label><input id="admin-teams" type="number" value="16" min="12" max="128"></div><div class="form-field"><label for="admin-prize">סך פרסים בשקלים</label><input id="admin-prize" type="number" value="2500" min="0"></div></div><label for="admin-format">פורמט תחרות</label><select id="admin-format"><option>נוקאאוט · הטוב משלושה</option><option>שלב בתים ונוקאאוט</option></select><button class="btn" style="margin-top:25px" type="submit">שמירת פרטים</button></form>`:`<div class="panel"><h3>יומן פעולות</h3>${[[state.results?'תוצאת NOVA FIVE מול IRON CORE אושרה':'צילום תוצאה התקבל וממתין לבדיקה','מנהל טורניר · היום, 18:42'],[state.approved?'TEAM ZERO אושרה לטורניר':'TEAM ZERO שלחה בקשת הרשמה','היום, 17:20'],['פרטי הטורניר פורסמו','מנהל טורניר · 19.10, 12:00']].map(([t,d])=>`<div class="notification">${t}<small>${d}</small></div>`).join('')}</div>`}`}
function match(){return `${pageTitle('MATCH CENTER','המשחק שלכם','גביע הקהילה הישראלי · רבע גמר · הטוב משלושה')}<div class="panel"><div class="flex between">${badge(state.results?'הסתיים':'ממתין למוכנות',state.results?'':'neutral')}<span class="muted" dir="ltr">29.10.2026 · 20:00</span></div><div class="versus" style="margin:35px 0"><div>${avatar('N','team',true)}<small>NOVA FIVE</small></div><div class="score">${state.results?'2 : 0':'VS'}</div><div>${avatar('I','orange',true)}<small>IRON CORE</small></div></div><div class="flex wrap" style="justify-content:center">${btn(state.ready?'המוכנות אושרה':'אישור מוכנות',"state.ready=true;save();render();toast('הקבוצה מוכנה למשחק')")}${btn('דיווח תוצאה',"reportResult()",'secondary')}${btn('פנייה למנהל',"support()",'ghost')}</div></div><div class="grid cols2" style="margin-top:20px"><div class="panel"><h3>לקראת המשחק</h3><p class="muted">כל חמשת השחקנים צריכים להיות זמינים 10 דקות לפני תחילת המשחק. פרטי החדר יופיעו למשתתפים לקראת הפתיחה.</p><div class="small-row"><b>מזהה חדר</b><span class="spacer"></span><span class="muted">יוצג לפני המשחק</span></div><div class="small-row"><b>מנהל המשחק</b><span class="spacer"></span><span>Nexus Admin</span></div></div><div class="panel"><h3>הרכב NOVA FIVE</h3>${members.map(([n,r,a],i)=>`<div class="small-row">${avatar(a,i%2?'purple':'team')}<b>${n}</b><span class="spacer"></span><span class="role">${r}</span></div>`).join('')}</div></div>`}
function render(){route=location.hash.slice(1)||'home';if(!['home','tournaments','tournament','live','register','squad','leaderboard','player','settings','signup','admin','match'].includes(route))route='home';renderShell();$('#app').innerHTML=({home,tournaments:tourneys,tournament:()=>detail(false),live:()=>detail(true),register,squad,leaderboard:leaders,player,settings,signup,admin,match})[route]();}
function search(q){q=q.trim();if(!q)return;filter=q.includes('ליגה')||q.includes('סתיו')?'live':q.includes('חדש')||q.includes('דור')?'soon':'open';go('tournaments');toast('תוצאות חיפוש בטורנירי ההדגמה')}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
let modalLastFocus;function openModal(t,body){modalLastFocus=document.activeElement;$('#modal').innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-top"><h2 id="modal-title">${t}</h2><button class="iconbtn" aria-label="סגירת חלון" onclick="closeModal()">${icon('close')}</button></div>${body}</section>`;$('#modal').hidden=false;document.body.style.overflow='hidden';$('#modal button, #modal input')?.focus()}
function closeModal(){$('#modal').hidden=true;document.body.style.overflow='';modalLastFocus?.focus()}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});document.addEventListener('keydown',e=>{if($('#modal').hidden)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const els=[...$('#modal').querySelectorAll('button,input,select,a')].filter(x=>!x.disabled);const f=els[0],l=els.at(-1);if(e.shiftKey&&document.activeElement===f){e.preventDefault();l.focus()}else if(!e.shiftKey&&document.activeElement===l){e.preventDefault();f.focus()}}});
function notifications(){openModal('ההתראות שלך',`<div class="notification">${icon('cup',17)} גביע הקהילה מתקרב<small>השלימו הרשמה עד 27.10 בשעה 23:59</small><button class="link" style="margin-top:10px" onclick="closeModal();go('tournament')">לפרטי הטורניר</button></div><div class="notification">${icon('users',17)} יש בקשות הצטרפות חדשות<small>${state.requests} שחקנים רוצים להצטרף ל־NOVA FIVE</small><button class="link" style="margin-top:10px" onclick="closeModal();squadTab='requests';go('squad')">לניהול בקשות</button></div><p>התראות לדוגמה עבור האבטיפוס.</p>`)}
function accountMenu(){openModal('החשבון שלך',`<div class="sidenav"><a href="#player" onclick="selectedPlayer='EfiX';closeModal()">${icon('user')} פרופיל השחקן שלי</a><a href="#settings" onclick="closeModal()">${icon('settings')} הגדרות חשבון</a><a href="#admin" onclick="closeModal()">${icon('shield')} ממשק מנהל טורניר</a><a href="#signup" onclick="closeModal()">${icon('plus')} תצוגת הרשמה לפלטפורמה</a></div>`)}
function nextReg(){if(!regChoice)return toast('בחרו איך תרצו להצטרף');regStep=1;render()}
function toggleRole(r,el){state.roles=state.roles.includes(r)?state.roles.filter(x=>x!==r):[...state.roles,r];el.classList.toggle('selected',state.roles.includes(r));save()}
function completeReg(){if(!$('#rules-check').checked)return toast('יש לאשר את חוקי הטורניר');if(regChoice==='solo'&&!state.roles.length)return toast('בחר לפחות תפקיד אחד');if(regChoice==='new'){let n=$('#new-team-name').value.trim();if(!n)return toast('יש להזין שם קבוצה');state.teamName=n}if(regChoice==='squad')state.joined=true;regStep=2;save();render()}
function requestSquad(n){if(state['request'+n])return toast('הבקשה כבר ממתינה לאישור הקפטן');state['request'+n]=true;save();render();toast(`בקשת הצטרפות ל־${n} נשלחה בהדגמה`)}
function createSquad(){openModal('פתיחת סקוואד',`<form onsubmit="event.preventDefault();const n=document.getElementById('squad-name').value.trim();if(!n)return;state.teamName=n;state.squad=true;save();closeModal();render();toast('הסקוואד נוצר בהדגמה')"><label for="squad-name">שם הסקוואד</label><input id="squad-name" required maxlength="30" placeholder="שם הקבוצה שלכם"><p>תהפכו לקפטן ותוכלו להזמין שחקנים. נתוני החברים והביצועים באבטיפוס יישארו נתוני דוגמה.</p><button type="submit" class="btn full">יצירת סקוואד</button></form>`)}
function openRecruit(){openModal('מוצאים את החמישי שלכם',`<p>שחקנים שמחפשים קבוצה · נתוני הדגמה</p><label for="recruit-role">סינון לפי תפקיד</label><select id="recruit-role" onchange="document.querySelectorAll('[data-recruit-role]').forEach(e=>e.hidden=this.value!=='all'&&e.dataset.recruitRole!==this.value)"><option value="all">כל התפקידים</option>${['Roam','Mid','Jungle'].map(r=>`<option>${r}</option>`).join('')}</select>${[['NinjaIL','Roam','1,260'],['Pixel','Jungle','1,290'],['Aero','Mid','1,310']].map(([n,r,e],i)=>`<div class="small-row" data-recruit-role="${r}">${avatar(n.slice(0,2),i%2?'purple':'team')}<div><b>${n}</b><small>${r} · ELO ${e}</small></div><span class="spacer"></span><button class="btn small secondary" onclick="this.textContent='הוזמן';this.disabled=true;invite('${n}')">הזמנה</button></div>`).join('')}`)}
function invite(n){toast(`הזמנה ל־${n} נשלחה בהדגמה`)}
function approveRequest(n){state.handledRequests=[...(state.handledRequests||[]),n];state.requests=Math.max(0,state.requests-1);save();render();toast(`הבקשה של ${n} אושרה בהדגמה`)}
function rejectRequest(n){state.handledRequests=[...(state.handledRequests||[]),n];state.requests=Math.max(0,state.requests-1);save();render();toast(`הבקשה של ${n} נדחתה בהדגמה`)}
function manageMember(n){openModal(`ניהול ${n}`,`<p>בחרו פעולה עבור חבר הסקוואד. הרכב שכבר ננעל לטורניר דורש תהליך שינוי נפרד.</p><div class="flex wrap">${btn('העברת קפטן',`confirmMember('${n}','captain')`,'secondary')}${btn('הסרה מהסקוואד',`confirmMember('${n}','remove')`,'danger')}</div>`)}
function confirmMember(n,action){openModal(action==='remove'?'הסרת חבר סקוואד':'העברת תפקיד הקפטן',`<p>הפעולה על ${n} תוצג כהדגמה בלבד ולא תשנה את הרכב הדוגמה.</p>${btn('אישור הדגמה',`closeModal();toast('הפעולה הודגמה בהצלחה')`)} ${btn('ביטול','closeModal()','ghost')}`)}
function support(){openModal('פנייה למנהל הטורניר',`<form onsubmit="event.preventDefault();closeModal();toast('הפנייה נקלטה בהדגמה. לא נשלחה הודעה אמיתית')"><label for="support-topic">נושא הפנייה</label><select id="support-topic"><option>בעיה בהרשמה</option><option>בעיה במשחק</option><option>ערעור על תוצאה</option></select><label for="support-message" style="margin-top:20px">תיאור קצר</label><input id="support-message" required placeholder="איך נוכל לעזור?" maxlength="500"><p>הטופס מדגים פנייה לצוות הטורניר בלבד.</p><button class="btn full" type="submit">שליחת פנייה בהדגמה</button></form>`)}
function streamDemo(){openModal('תצוגת שידור חי',`<div class="stream"><div>${icon('play',40)}<h3 style="margin-top:15px">WOLFPACK vs PHANTOM</h3><p>כאן יוצג נגן השידור של הטורניר.<br>לא מחובר מקור שידור באבטיפוס.</p></div></div>`)}
function reportResult(){openModal('דיווח תוצאת משחק',`<form onsubmit="event.preventDefault();closeModal();toast('דיווח הדוגמה הועבר לתור אישור מנהל')"><p>התוצאה תוצג לאחר אישור מנהל הטורניר.</p><div class="form-grid"><div><label for="score-a">NOVA FIVE</label><input id="score-a" type="number" min="0" max="2" value="2" required></div><div><label for="score-b">IRON CORE</label><input id="score-b" type="number" min="0" max="2" value="0" required></div></div><label for="match-image" style="margin-top:20px">צילום תוצאה</label><input type="file" id="match-image" accept="image/*"><button type="submit" class="btn full" style="margin-top:20px">שליחת דיווח בהדגמה</button></form>`)}
function resultUpload(el){const file=el.files[0];if(!file)return;if(!file.type.startsWith('image/'))return toast('יש לבחור קובץ תמונה');if(file.size>10*1024*1024)return toast('בחרו תמונה עד 10 מגה־בייט');const reader=new FileReader();reader.onload=()=>{$('#result-preview').innerHTML=`<img alt="תצוגה מקדימה של צילום התוצאה שבחרת" style="max-width:100%;max-height:220px;object-fit:contain;border-radius:8px" src="${reader.result}"><p class="hint">התמונה מוצגת מקומית בלבד. הטבלה שמתחת מכילה נתוני דוגמה.</p>`};reader.readAsDataURL(file);toast('הצילום מוכן לבדיקה. טבלת הדוגמה זמינה לתיקון')}
function approveResult(){if(state.results)return toast('התוצאה כבר אושרה');state.results=true;save();render();toast('תוצאת הדוגמה אושרה. יומן הפעולות ומצב המשחק עודכנו')}
function saveSettings(e){e.preventDefault();state.name=$('#account-name').value.trim();state.nick=$('#account-nick').value.trim();state.card=$('#member-card').value.trim();save();render();toast('פרטי הפרופיל נשמרו בדפדפן')}
function togglePreference(i,el){state['toggle'+i]=!(state['toggle'+i]!==false);save();el.classList.toggle('off',!state['toggle'+i]);el.setAttribute('aria-pressed',state['toggle'+i])}
function signupSubmit(e){e.preventDefault();if(signupStep===0){state.name=$('#signup-name').value.trim();signupStep=1;render()}else{if(!state.roles.length)return toast('בחרו תפקיד אחד לפחות');state.nick=$('#signup-nick').value.trim();state.card=$('#signup-card').value.trim();state.squad=$('#signup-status').value==='team';save();go('home');toast('ברוכים הבאים לזירת ההדגמה')}}
function resetDemo(){openModal('איפוס ההדגמה',`<p>הפרטים והפעולות ששמרתם בדפדפן יוחזרו לנתוני הדוגמה הראשוניים.</p>${btn('איפוס',"state={...defaultState,roles:['Mid']};save();closeModal();go('home');toast('ההדגמה אופסה')",'danger')} ${btn('ביטול','closeModal()','ghost')}`)}
window.addEventListener('hashchange',()=>{if(!$('#modal').hidden)closeModal();render();window.scrollTo({top:0,behavior:'instant'})});render();

function openUpcoming(){openModal('טורניר הדור הבא',`<div class="tourney-cover cover-orange" style="border-radius:8px"><div class="cover-word">NEXT GEN<small>MOBILE LEGENDS · ISRAEL</small></div>${badge('בקרוב','neutral')}</div><p>טורניר לשחקנים חדשים · 05.11.2026 בשעה 19:00.<br>16 קבוצות · סך פרסים לדוגמה ₪1,000.</p><p>ההרשמה עדיין לא נפתחה. אפשר לעקוב אחר פתיחתה דרך מרכז ההתראות.</p>${btn(state.followNext?'מעקב פעיל':'עדכנו אותי כשההרשמה נפתחת',"state.followNext=true;save();closeModal();toast('המעקב הופעל בהדגמה. לא נוצרה תזכורת אמיתית')",'full')}`)}
